            $stmt=$db->prepare("SELECT s.* FROM support_services s JOIN project_services ps ON ps.support_service_id=s.id WHERE s.active=1 AND ps.project_id=?");$stmt->execute([$projectId]);$allowedProjectServices=enrich_support_services($db,$stmt->fetchAll());$allowedProjectServiceIds=array_map('intval',array_column($allowedProjectServices,'id'));$projectServicesById=[];foreach($allowedProjectServices as $allowedService)$projectServicesById[(int)$allowedService['id']]=$allowedService;
