            $db->prepare('DELETE FROM project_service_rollout_objects WHERE project_id=?')->execute([$projectId]);
            $mappingInsert=$db->prepare('INSERT INTO project_service_rollout_objects(project_id,support_service_id,rollout_object_id) VALUES(?,?,?)');
            foreach((array)($_POST['service_rollout']??[]) as $serviceId=>$objectIds){$serviceId=(int)$serviceId;if(!isset($projectServicesById[$serviceId]))continue;foreach((array)$objectIds as $objectId=>$selected){$objectId=(int)$objectId;if(isset($allowedObjects[$objectId])&&service_applies_to_rollout_object($projectServicesById[$serviceId],$allowedObjects[$objectId]))$mappingInsert->execute([$projectId,$serviceId,$objectId]);}}
            $projectInsert=$db->prepare('INSERT INTO project_support_matrix(project_id,support_service_id,provider_id,offered,delivery_mode,delivery_partner,schedule,note) VALUES(?,?,?,?,?,?,?,?)');
            foreach ((array)($_POST['project_cell']??[]) as $serviceId=>$serviceProviders){$serviceId=(int)$serviceId;if(!in_array($serviceId,$allowedProjectServiceIds,true))continue;foreach($serviceProviders as $providerId=>$cell){$providerId=(int)$providerId;if(!in_array($providerId,$allowedProviderIds,true)||!service_applies_to_provider($projectServicesById[$serviceId],$providersById[$providerId],$projectClassObject))continue;[$offered,$deliveryMode,$deliveryPartner,$schedule,$note]=$cellValues((array)$cell,$providerId,$projectServicesById[$serviceId]);if($offered||$deliveryMode!==''||$deliveryPartner!==''||$schedule!==''||$note!=='')$projectInsert->execute([$projectId,$serviceId,$providerId,$offered,$deliveryMode,$deliveryPartner,$schedule,$note]);}}
            sync_mandatory_services($db,null,$projectId);
            $db->commit(); flash('success','Projektmatrix gespeichert.'); redirect('?page=matrix&project_id='.$projectId);
        }
        if ($action === 'import_preview') {
            $requestedMode=post_string('import_mode');$mode=in_array($requestedMode,['feedback','planning','structure'],true)?$requestedMode:'feedback';$uploads=import_uploaded_files();$allRows=[];$files=[];
            foreach($uploads as $sourceIndex=>$upload){$prepared=prepare_import_wizard($db,read_import_rows($upload['tmp_name'],$upload['extension']));foreach($prepared as &$preparedRow){$preparedRow['source_index']=$sourceIndex;$preparedRow['source_file']=$upload['name'];}unset($preparedRow);if($mode!=='structure')$prepared=match_existing_import_targets($db,$prepared);$providerId=$mode==='feedback'?detect_feedback_provider($db,$upload['name'],$prepared):0;if($providerId)foreach($prepared as &$preparedRow)$preparedRow['provider_id']=$providerId;unset($preparedRow);$files[]=['index'=>$sourceIndex,'name'=>$upload['name'],'provider_id'=>$providerId];array_push($allRows,...$prepared);}
            $_SESSION['import_wizard']=['token'=>bin2hex(random_bytes(16)),'kind'=>'data','stage'=>'review','mode'=>$mode,'files'=>$files,'rows'=>$allRows];
            redirect('?page=import');
        }
        if ($action === 'import_cancel') {
            unset($_SESSION['import_wizard']);
            flash('info','Importvorschau verworfen.');redirect('?page=import');
        }
        if ($action === 'import_compare') {
            $wizard=$_SESSION['import_wizard']??null;
            if(!$wizard||!hash_equals((string)$wizard['token'],post_string('wizard_token')))throw new RuntimeException('Die Importvorschau ist nicht mehr gültig. Bitte die Datei erneut hochladen.');
            $reviewPayload=json_decode((string)($_POST['review_payload']??''),true);if(!is_array($reviewPayload))throw new RuntimeException('Die geprüften Importdaten konnten nicht gelesen werden.');$postedRows=is_array($reviewPayload['rows']??null)?$reviewPayload['rows']:$reviewPayload;$fileAssignments=is_array($reviewPayload['files']??null)?$reviewPayload['files']:[];
            $reviewRows=merge_import_review((array)$wizard['rows'],$postedRows);$mode=in_array(($wizard['mode']??''),['feedback','planning','structure'],true)?$wizard['mode']:'structure';if($mode==='feedback'){$reviewRows=apply_feedback_file_providers($db,$reviewRows,$fileAssignments);foreach($_SESSION['import_wizard']['files'] as &$file)$file['provider_id']=(int)($fileAssignments[(string)$file['index']]??0);unset($file);}$_SESSION['import_wizard']['rows']=$reviewRows;
            $reviewedRows=reviewed_import_rows($db,$reviewRows,$mode);$preview=simulate_import_changes($db,static fn()=>import_rows($db,$reviewedRows,$mode!=='structure',$mode!=='feedback',$mode==='planning',false));$_SESSION['import_wizard']['kind']='data';$_SESSION['import_wizard']['stage']='confirm';$_SESSION['import_wizard']['reviewed_rows']=$reviewedRows;$_SESSION['import_wizard']['changes']=$preview['changes'];$_SESSION['import_wizard']['result']=$preview['result'];$_SESSION['import_wizard']['state_hash']=$preview['state_hash'];redirect('?page=import');
        }
        if($action==='import_back'){$wizard=$_SESSION['import_wizard']??null;if(!$wizard||!hash_equals((string)$wizard['token'],post_string('wizard_token')))throw new RuntimeException('Die Importvorschau ist nicht mehr gültig.');if(($wizard['kind']??'')==='catalog'){unset($_SESSION['import_wizard']);flash('info','Katalogvorschau verworfen. Bitte die Datei bei Bedarf erneut auswählen.');}else{$_SESSION['import_wizard']['stage']='review';unset($_SESSION['import_wizard']['reviewed_rows'],$_SESSION['import_wizard']['changes'],$_SESSION['import_wizard']['result'],$_SESSION['import_wizard']['state_hash']);}redirect('?page=import');}
        if ($action === 'import_apply') {
