        }
    } catch (Throwable $error) {
        if ($db->inTransaction()) $db->rollBack();
        flash('danger',$error instanceof PDOException && str_contains($error->getMessage(),'UNIQUE') ? 'Dieser Eintrag ist bereits vorhanden.' : $error->getMessage());
        redirect($_SERVER['HTTP_REFERER'] ?? '?');
    }
}

if ($page === 'export') {
    require_login();
    try {
        export_data($db,(string)($_GET['format']??'csv'));
    } catch (Throwable $error) {
        flash('danger','Der Export konnte nicht erstellt werden: '.$error->getMessage());
        redirect('?page=import');
    }
}
if ($page === 'template') {
    require_login();
    try {
        $type=(string)($_GET['type']??'tpl');
        $includeProviderData=(string)($_GET['include_provider_data']??'')==='1';
        if($type==='tpl-projects')download_tpl_template_archive($db,$includeProviderData);
        if($type==='tpl-project')download_tpl_template($db,(int)($_GET['project_id']??0),$includeProviderData);
        if($type==='phase-fi-dsv')download_provider_template_archive($db,['FI','DSV'],'FI-DSV-Unterstuetzungsplanung');
        if($type==='phase-rv')download_provider_template_archive($db,['RV'],'Regionalverbaende-Unterstuetzungsabfrage');
        if(in_array($type,['catalog-rv','catalog-fi','catalog-dsv'],true))download_catalog_maintenance($db,strtoupper(substr($type,8)));
        if($type==='providers')download_provider_template_archive($db,['FI','DSV','RV'],'Rollout-Unterstuetzung-Leistungserbringer');
        if($type==='provider')download_provider_template($db,(int)($_GET['provider_id']??0));
        download_tpl_template($db,0,$includeProviderData);
    } catch (Throwable $error) {
        flash('danger','Die Excel-Vorlage konnte nicht erstellt werden: '.$error->getMessage());
        redirect('?page=import');
    }
}
if ($userCount === 0) render_auth('setup',$config);
if (!is_logged_in()) render_auth('login',$config);

render_header($config,$page,$db);
switch ($page) {
    case 'project': render_project($db,(int)($_GET['id']??0)); break;
    case 'object': render_object_form($db,(int)($_GET['project_id']??0),(int)($_GET['id']??0)); break;
    case 'matrix': render_matrix($db,(int)($_GET['project_id']??0),(int)($_GET['id']??0)); break;
    case 'custom-service': render_custom_service_form($db,(int)($_GET['project_id']??0),(int)($_GET['object_id']??0),(int)($_GET['id']??0)); break;
    case 'catalog': render_catalog($db,(int)($_GET['edit']??0)); break;
    case 'providers': render_providers($db); break;
    case 'import': render_import($db); break;
    default: render_dashboard($db);
}
render_footer();

