se DSV</label><select class="form-select" name="dsv_class"><option value="">– nicht festgelegt –</option><?php foreach($dsvLevels as $level):?><option value="<?=e($level['class_code'])?>" <?=($object['dsv_class_code']??'')===$level['class_code']?'selected':''?>><?=e($level['class_label'])?></option><?php endforeach;?></select></div><div class="col-12"><div class="form-text">Klasse 0 bedeutet: Für dieses Rolloutobjekt ist beim jeweiligen Verbundpartner keine Unterstützungsleistung erforderlich.</div></div><div class="col-12"><label class="form-label">Anmerkungen</label><textarea class="form-control" rows="4" name="notes"><?=e($object['notes'])?></textarea></div><div class="col-12 d-flex gap-2"><button class="btn btn-primary">Speichern und Matrix öffnen</button><a class="btn btn-outline-secondary" href="?page=project&id=<?=$projectId?>">Abbrechen</a></div></div></form><?php if($id): ?><form method="post" class="mt-3"><?=csrf_field()?><input type="hidden" name="action" value="delete_object"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="project_id" value="<?=$projectId?>"><button class="btn btn-link text-danger px-0" data-confirm="Rolloutobjekt und Matrix wirklich löschen?">Rolloutobjekt löschen</button></form><?php endif; ?><?php }

function render_matrix(PDO $db,int $projectId,int $legacyObjectId=0): void {
    if(!$projectId&&$legacyObjectId){$stmt=$db->prepare('SELECT project_id FROM rollout_objects WHERE id=?');$stmt->execute([$legacyObjectId]);$projectId=(int)$stmt->fetchColumn();}
    $stmt=$db->prepare('SELECT * FROM projects WHERE id=?');$stmt->execute([$projectId]);$project=$stmt->fetch();
    if(!$project){echo '<div class="alert alert-danger">Projekt nicht gefunden.</div>';return;}
    $stmt=$db->prepare('SELECT * FROM rollout_objects WHERE project_id=? ORDER BY start_date,name');$stmt->execute([$projectId]);$objects=enrich_rollout_objects($db,$stmt->fetchAll());
    $providers=$db->query("SELECT * FROM providers WHERE active=1 ORDER BY CASE type WHEN 'FI' THEN 1 WHEN 'DSV' THEN 2 ELSE 3 END,sort_order,name")->fetchAll();
    $stmt=$db->prepare('SELECT * FROM project_provider_contacts WHERE project_id=?');$stmt->execute([$projectId]);$projectContacts=[];foreach($stmt as $contact)$projectContacts[$contact['provider_id']]=$contact;

    $allStandardProjectServices=enrich_support_services($db,$db->query("SELECT * FROM support_services WHERE active=1 AND is_standard=1 ORDER BY name COLLATE NOCASE")->fetchAll());
    $projectClassScope=project_rollout_class_scope($db,$projectId);
    $projectFunctionalMax=$projectClassScope['functional']?$projectClassScope['functional'][count($projectClassScope['functional'])-1]:null;$projectTechnicalMax=$projectClassScope['technical']?$projectClassScope['technical'][count($projectClassScope['technical'])-1]:null;$projectDsvMax=$projectClassScope['dsv']?$projectClassScope['dsv'][count($projectClassScope['dsv'])-1]:null;$dsvLevels=provider_class_levels($db,'DSV');$dsvLabels=array_column($dsvLevels,'class_label','class_code');
    $projectClassObject=['functional_class'=>$projectFunctionalMax,'technical_class'=>$projectTechnicalMax,'dsv_class_code'=>$projectDsvMax];
    $standardProjectGroups=service_selection_groups($allStandardProjectServices,$projectClassScope['functional'],$projectClassScope['technical'],$projectClassScope['dsv']);
    $selectableStandardIds=service_selection_group_ids($standardProjectGroups);$selectableStandardIdMap=array_fill_keys($selectableStandardIds,true);
    $standardProjectServices=array_values(array_filter($allStandardProjectServices,fn($service)=>isset($selectableStandardIdMap[(int)$service['id']])));
    $stmt=$db->prepare('SELECT ps.support_service_id FROM project_services ps JOIN support_services s ON s.id=ps.support_service_id WHERE ps.project_id=? AND s.is_standard=1');$stmt->execute([$projectId]);$selectedProjectServiceIds=array_map('intval',array_column($stmt->fetchAll(),'support_service_id'));
    $stmt=$db->prepare("SELECT s.* FROM support_services s JOIN project_services ps ON ps.support_service_id=s.id WHERE s.active=1 AND ps.project_id=? ORDER BY s.name COLLATE NOCASE");$stmt->execute([$projectId]);$projectServices=array_values(array_filter(enrich_support_services($db,$stmt->fetchAll()),fn($service)=>!$service['is_standard']||isset($selectableStandardIdMap[(int)$service['id']])));
    $projectMandatory=mandatory_project_pairs($db,$projectId);
    $stmt=$db->prepare('SELECT * FROM project_support_matrix WHERE project_id=?');$stmt->execute([$projectId]);$projectMatrix=[];foreach($stmt as $cell)$projectMatrix[$cell['support_service_id']][$cell['provider_id']]=$cell;
    $stmt=$db->prepare('SELECT support_service_id,rollout_object_id FROM project_service_rollout_objects WHERE project_id=?');$stmt->execute([$projectId]);$serviceRolloutUsage=[];foreach($stmt->fetchAll() as $mapping)$serviceRolloutUsage[(int)$mapping['support_service_id']][(int)$mapping['rollout_object_id']]=true; ?>
<div class="project-matrix-page"><div class="d-flex flex-wrap justify-content-between align-items-start gap-3 mb-4"><div><a class="small text-secondary text-decoration-none" href="?page=project&id=<?=$projectId?>">← Projekt</a><h1 class="page-title h2 mt-2 mb-1"><?=e($project['name'])?></h1><div class="text-secondary">Projektleistungen auswählen, ihre Nutzung je Rolloutobjekt festlegen und Rückmeldungen zusammenführen</div></div><a class="btn btn-outline-secondary" href="?page=project&id=<?=$projectId?>">Projekt bearbeiten</a></div>
<div class="alert alert-light border small matrix-info">Unterstützungsleistungen werden dem Projekt zugeordnet und anschließend je Rolloutobjekt genutzt. Die Klassen hängen ausschließlich an den Rolloutobjekten: Bankfachlich A–D, FI 1–3 und DSV nach dem unter „Leistungserbringer“ gepflegten Schema.</div>
<div class="class-color-legend mb-3" aria-label="Farblegende der Leistungsklassen"><span class="small fw-semibold text-muted me-1">Bankfachlicher Rollout</span><?php foreach(['A','B','C','D'] as $class):?><span class="badge service-class-badge class-tone-functional-<?=strtolower($class)?>"><?=$class?></span><?php endforeach;?><span class="small fw-semibold text-muted ms-2 me-1">FI</span><?php foreach(['1','2','3'] as $class):?><span class="badge service-class-badge class-tone-technical-<?=$class?>"><?=$class?></span><?php endforeach;?><span class="small fw-semibold text-muted ms-2 me-1">DSV</span><?php foreach($dsvLevels as $index=>$level):?><span class="badge service-class-badge class-tone-technical-<?=min(3,$index+1)?>"><?=e($level['class_label'])?></span><?php endforeach;?><span class="small text-muted ms-2">blass = niedrigere Klasse · kräftig = höhere Klasse</span></div>
<div class="delivery-legend mb-3"><span class="delivery-key delivery-self">Selbst</span><span class="delivery-key delivery-other">Anderer RV</span><span class="delivery-key delivery-external">Externer DL</span><span class="delivery-key delivery-none">Keine Bereitstellung</span><span class="delivery-key delivery-open">Noch offen</span></div>
<form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save_matrix"><input type="hidden" name="project_id" value="<?=$projectId?>">
<div class="card p-3 p-lg-4 mb-4 matrix-full-width"><h2 class="h5 mb-1">Standardleistungen für dieses Projekt auswählen</h2><p class="small text-secondary mb-2">Die Auswahl wird aus den Klassen der einzelnen Rolloutobjekte abgeleitet.</p><p class="small text-secondary mb-4">Die Klassen gelten kumulativ. Mehrfach klassifizierte Leistungen erscheinen in mehreren passenden Bereichen; die Auswahl wird automatisch synchronisiert.</p>
<?php if($standardProjectServices):$selectionAreas=['functional'=>['title'=>'Bankfachlicher Rollout','classes'=>['A','B','C','D'],'labels'=>[]],'technical'=>['title'=>'FI','classes'=>['1','2','3'],'labels'=>[]],'dsv'=>['title'=>'DSV','classes'=>array_column($dsvLevels,'class_code'),'labels'=>$dsvLabels]];foreach($selectionAreas as $dimension=>$area):$areaCount=array_sum(array_map('count',$standardProjectGroups[$dimension]));if(!$areaCount)continue;?>
<section class="service-selection-area <?=$dimension==='technical'?'service-selection-area-technical':''?>"><div class="d-flex flex-wrap align-items-baseline gap-2 mb-3"><h3 class="h6 mb-0"><?=e($area['title'])?></h3><span class="small text-secondary"><?=$areaCount?> <?=$areaCount===1?'Leistung':'Leistungen'?></span></div>
<?php foreach($area['classes'] as $class):$classServices=$standardProjectGroups[$dimension][$class]??[];if(!$classServices)continue;$displayClass=$area['labels'][$class]??$class;$tone=$dimension==='functional'?'functional-'.strtolower($class):'technical-'.min(3,max(1,(int)preg_replace('/\D+/','',$class)));?><div class="service-selection-class mb-4"><div class="service-selection-class-header"><span class="catalog-group-class class-tone-<?=$tone?>"><?=e($displayClass)?></span><span class="fw-semibold">Klasse <?=e($displayClass)?></span><span class="small text-secondary"><?=count($classServices)?> <?=count($classServices)===1?'Leistung':'Leistungen'?></span></div><div class="row row-cols-1 row-cols-md-2 row-cols-xl-3 row-cols-xxl-4 g-2 mt-1">
<?php foreach($classServices as $service):?><div class="col"><label class="form-check service-option border rounded p-2 ps-5 h-100"><input class="form-check-input" type="checkbox" name="project_standard_service[]" value="<?=$service['id']?>" data-service-selection="<?=$service['id']?>" <?=in_array((int)$service['id'],$selectedProjectServiceIds,true)?'checked':''?>><span class="fw-semibold"><?=e($service['name'])?></span><span class="service-class-badges mt-1"><?=service_class_badges($service)?></span><?php if($service['description']):?><span class="d-block small text-secondary mt-1"><?=e($service['description'])?></span><?php endif;?></label></div><?php endforeach;?></div></div><?php endforeach;?></section><?php endforeach;?>
<?php else:?><div class="alert alert-light border small mb-0"><?php if(!$projectFunctionalMax&&!$projectTechnicalMax&&!$projectDsvMax):?>Für dieses Projekt ist noch keine Rolloutklasse über seine Rolloutobjekte festgelegt. Sobald mindestens ein Rolloutobjekt klassifiziert ist, erscheinen hier die kumulativ passenden Unterstützungsleistungen.<?php elseif(!$allStandardProjectServices):?>Im Standardkatalog sind noch keine Standardleistungen angelegt.<?php else:?>Für die ermittelten Rolloutklassen sind im Standardkatalog keine passenden Unterstützungsleistungen hinterlegt.<?php endif;?></div><?php endif;?></div>
<div class="card p-3 mb-4 matrix-full-width"><h2 class="h5 mb-1">Nutzung der Projektleistungen je Rolloutobjekt</h2><p class="small text-secondary mb-3">Alle Leistungen sind dem Projekt zugeordnet. Hier wird lediglich angehakt, bei welchen Rolloutobjekten die jeweilige Projektleistung genutzt wird.</p><?php if(!$objects):?><div class="alert alert-light border small mb-0">Noch keine Rolloutobjekte vorhanden.</div><?php elseif(!$projectServices):?><div class="alert alert-light border small mb-0">Bitte zuerst oben mindestens eine Standardleistung auswählen und speichern oder eine zusätzliche Projektleistung anlegen.</div><?php else:?><div class="table-responsive"><table class="table table-sm table-bordered align-middle mb-0"><thead><tr><th>Projektleistung</th><?php foreach($objects as $object):?><th class="text-center"><span class="d-block"><?=e($object['name'])?></span><span class="small fw-normal text-secondary"><?=e(class_label($object))?></span></th><?php endforeach;?></tr></thead><tbody><?php foreach($projectServices as $service):?><tr><th><span class="fw-semibold"><?=e($service['name'])?></span><span class="service-class-badges mt-1"><?=service_class_badges($service)?></span></th><?php foreach($objects as $object):$applicable=service_applies_to_rollout_object($service,$object);?><td class="text-center"><?php if($applicable):?><input class="form-check-input" type="checkbox" name="service_rollout[<?=$service['id']?>][<?=$object['id']?>]" value="1" <?=isset($serviceRolloutUsage[$service['id']][$object['id']])?'checked':''?> aria-label="<?=e($service['name'].' für '.$object['name'])?>"><?php else:?><span class="text-secondary" title="Für die Klassen dieses Rolloutobjekts nicht passend">–</span><?php endif;?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php endif;?></div>
<div class="card p-3 mb-4 matrix-full-width"><h2 class="h5 mb-1">Ansprechpartner der Leistungserbringer</h2><p class="small text-secondary">Je Projekt wird für FI, DSV und jeden Regionalverband genau ein Ansprechpartner hinterlegt.</p><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Leistungserbringer</th><th>Ansprechpartner</th><th>Telefonnummer</th></tr></thead><tbody><?php foreach($providers as $provider):$contact=$projectContacts[$provider['id']]??null;?><tr><td class="fw-semibold"><?=e($provider['name'])?></td><td><input class="form-control form-control-sm" name="project_contact[<?=$provider['id']?>][contact_name]" value="<?=e($contact['contact_name']??'')?>" placeholder="Name"></td><td><input type="tel" class="form-control form-control-sm" name="project_contact[<?=$provider['id']?>][contact_phone]" value="<?=e($contact['contact_phone']??'')?>" placeholder="Telefonnummer"></td></tr><?php endforeach;?></tbody></table></div></div>
<div class="card matrix-wrap"><table class="table table-bordered matrix-table align-middle mb-0"><thead><tr><th>Ebene / Unterstützungsleistung</th><?php foreach($providers as $provider): ?><th class="text-center"><?=e($provider['name'])?></th><?php endforeach; ?></tr></thead><tbody>
<tr class="matrix-section"><th colspan="<?=count($providers)+1?>"><span class="badge text-bg-dark me-2">Projektleistungen</span><?=e($project['name'])?> <a class="btn btn-sm btn-outline-dark ms-3" href="?page=custom-service&project_id=<?=$projectId?>">+ Zusätzliche Projektleistung</a></th></tr>
<?php if(!$projectServices): ?><tr><td colspan="<?=count($providers)+1?>" class="text-secondary py-3">Noch keine projektweite Unterstützungsleistung zugeordnet.</td></tr><?php else: foreach($projectServices as $service)render_matrix_service_row($service,$providers,$projectMatrix,'project_cell',$projectMandatory,'project-'.$service['id'],$projectId,0,$projectClassObject);endif; ?>
</tbody></table></div><div class="mt-3 d-flex gap-2"><button class="btn btn-primary">Gesamte Projektmatrix speichern</button><a class="btn btn-outline-secondary" href="?page=catalog">Standardkatalog öffnen</a></div></form></div><script>(()=>{const update=select=>{const cell=select.closest('[data-delivery-cell]');if(!cell)return;cell.dataset.deliveryState=select.value||'open';cell.querySelector('[data-delivery-other]').hidden=select.value!=='other_rv';cell.querySelector('[data-delivery-external]').hidden=select.value!=='external';};document.querySelectorAll('[data-delivery-mode]').forEach(select=>{update(select);select.addEventListener('change',()=>update(select));});document.querySelectorAll('[data-service-selection]').forEach(box=>box.addEventListener('change',()=>{document.querySelectorAll('[data-service-selection="'+box.dataset.serviceSelection+'"]').forEach(peer=>peer.checked=box.checked);}));})();</script><?php }

function render_matrix_service_row(array $service,array $providers,array $matrix,string $prefix,array $mandatoryPairs,string $idPrefix,int $projectId,int $objectId,?array $object): void {
    $classLabel=support_service_class_label($service);$requiresDelivery=!empty($service['requires_delivery_source']); ?>
<tr><td><strong><?=e($service['name'])?></strong> <span class="badge rounded-pill text-bg-<?=$service['is_standard']?'secondary':'warning'?>"><?=$service['is_standard']?'Standard':'zusätzlich'?></span>
<?php if(!$service['is_standard']):?><a class="small ms-1" href="?page=custom-service&id=<?=$service['id']?>&project_id=<?=$projectId?><?=$objectId?'&object_id='.$objectId:''?>">Bearbeiten</a><?php endif;?>
<?php if($classLabel!==''):?><div class="service-class-badges mt-1"><?=service_class_badges($service)?></div><?php endif;?>
<?php if($service['mandatory_for_all']):?><div><span class="badge text-bg-danger mt-1">Obligatorisch</span></div><?php endif;?><?php if(empty($service['schedule_relevant'])):?><div><span class="badge text-bg-light border mt-1">Kein Termin/Zeitraum erforderlich</span></div><?php endif;?>
<?php if($service['description']):?><div class="small text-secondary mt-1"><?=e($service['description'])?></div><?php endif;?></td>
<?php foreach($providers as $provider):if(!service_applies_to_provider($service,$provider,$object)):?><td class="matrix-not-applicable text-center" title="Für diesen Leistungserbringer nicht vorgesehen">–</td><?php continue;endif;
    $cell=$matrix[$service['id']][$provider['id']]??null;$isMandatory=isset($mandatoryPairs[$service['id']][$provider['id']]);$scheduleRelevant=!empty($service['schedule_relevant']);$field=$prefix.'['.$service['id'].']['.$provider['id'].']';$detailsId='details-'.$idPrefix.'-'.$provider['id'];$isRv=$provider['type']==='RV';$useDelivery=$isRv&&$requiresDelivery&&!$isMandatory;$mode=normalize_delivery_mode((string)($cell['delivery_mode']??''));$partner=(string)($cell['delivery_partner']??'');$hasDetails=trim((string)($cell['note']??''))!==''||($scheduleRelevant&&trim((string)($cell['schedule']??''))!==''); ?>
<td class="text-center <?=$useDelivery?'delivery-cell':''?>" <?=$useDelivery?'data-delivery-cell data-delivery-state="'.e($mode?:'open').'"':''?>>
<?php if($useDelivery):?><select class="form-select form-select-sm delivery-mode" name="<?=$field?>[delivery_mode]" data-delivery-mode aria-label="Bereitstellungsart"><option value="" <?=$mode===''?'selected':''?>>Noch offen</option><option value="self" <?=$mode==='self'?'selected':''?>>Selbst</option><option value="other_rv" <?=$mode==='other_rv'?'selected':''?>>Anderer RV</option><option value="external" <?=$mode==='external'?'selected':''?>>Externer DL</option><?php if(!$isMandatory):?><option value="none" <?=$mode==='none'?'selected':''?>>Keine Bereitstellung</option><?php endif;?></select><div class="delivery-partner mt-2" data-delivery-other><label class="small text-secondary">Welcher RV?</label><select class="form-select form-select-sm" name="<?=$field?>[delivery_partner_other_rv]"><option value="">– auswählen –</option><?php foreach($providers as $otherProvider)if($otherProvider['type']==='RV'&&(int)$otherProvider['id']!==(int)$provider['id']):?><option value="<?=e($otherProvider['name'])?>" <?=$mode==='other_rv'&&$partner===$otherProvider['name']?'selected':''?>><?=e($otherProvider['name'])?></option><?php endif;?></select></div><div class="delivery-partner mt-2" data-delivery-external><label class="small text-secondary">Welcher Dienstleister?</label><input class="form-control form-control-sm" name="<?=$field?>[delivery_partner_external]" value="<?=e($mode==='external'?$partner:'')?>" placeholder="Name des Dienstleisters"></div><?php else:?><input class="matrix-check" type="checkbox" name="<?=$field?>[offered]" <?=$isMandatory||($cell&&$cell['offered'])?'checked':''?> <?=$isMandatory?'disabled title="Verpflichtende Basisleistung oder für alle zuständigen Leistungserbringer vorgegeben"':''?>><?php endif;?>
<button type="button" class="btn btn-link btn-sm p-1 d-block mx-auto <?=$hasDetails?'fw-bold text-danger':'text-secondary'?>" data-bs-toggle="collapse" data-bs-target="#<?=$detailsId?>"><?=$scheduleRelevant?'Termin / Bemerkung':'Bemerkung'?></button><div class="collapse mt-2 text-start matrix-details" id="<?=$detailsId?>"><?php if($scheduleRelevant):?><label class="small text-secondary">Termin / Zeitraum</label><input class="form-control form-control-sm mb-2" name="<?=$field?>[schedule]" value="<?=e($cell['schedule']??'')?>" placeholder="z. B. Oktober 2026"><?php endif;?><label class="small text-secondary">Bemerkung</label><textarea class="form-control form-control-sm" rows="2" name="<?=$field?>[note]" placeholder="Bemerkung zur Unterstützungsleistung"><?=e($cell['note']??'')?></textarea></div></td>
<?php endforeach;?></tr><?php }

function render_custom_service_form(PDO $db,int $projectId,int $objectId,int $id): void {
    $objectId=0;
    $service=['id'=>0,'name'=>'','description'=>'','project_id'=>$projectId,'mandatory_for_all'=>0,'schedule_relevant'=>1,'classes'=>'','provider_targets'=>['RV']];
    if($id){$stmt=$db->prepare('SELECT s.* FROM support_services s WHERE s.id=? AND s.is_standard=0');$stmt->execute([$id]);$service=$stmt->fetch()?:$service;if(!$service['id']){echo '<div class="alert alert-danger">Zusätzliche Leistung nicht gefunden.</div>';return;}$service=enrich_support_services($db,[$service])[0];$service['classes']=implode(',',$service['class_codes']);$projectId=(int)($service['project_id']?:$projectId);}
    $stmt=$db->prepare('SELECT name FROM projects WHERE id=?');$stmt->execute([$projectId]);$projectName=$stmt->fetchColumn();if(!$projectName){echo '<div class="alert alert-danger">Projekt nicht gefunden.</div>';return;}
    $selected=explode(',',(string)$service['classes']);$dsvLevels=provider_class_levels($db,'DSV'); ?>
<a class="small text-secondary text-decoration-none" href="?page=matrix&project_id=<?=$projectId?>">← Zur Projektmatrix</a><div class="mb-4 mt-2"><h1 class="page-title h2 mb-1"><?=$id?'Zusätzliche Leistung bearbeiten':'Zusätzliche Leistung anlegen'?></h1><p class="text-secondary mb-0">Dem Projekt <?=e((string)$projectName)?> zugeordnet</p></div>
<form method="post" class="card p-4 vstack gap-3" style="max-width:850px"><?=csrf_field()?><input type="hidden" name="action" value="save_custom_service"><input type="hidden" name="id" value="<?=$service['id']?>"><input type="hidden" name="project_id" value="<?=$projectId?>">
<div><label class="form-label">Bezeichnung</label><input class="form-control" name="name" value="<?=e($service['name'])?>" required></div><div><label class="form-label">Beschreibung</label><textarea class="form-control" rows="3" name="description"><?=e($service['description'])?></textarea></div>
<div data-cumulative-classes><label class="form-label d-block">Rolloutklasse Bankfachlich</label><?php foreach(['A','B','C','D'] as $c):?><label class="form-check form-check-inline"><input class="form-check-input" type="checkbox" name="functional[]" value="<?=$c?>" <?=in_array('functional:'.$c,$selected,true)?'checked':''?>> <?=$c?></label><?php endforeach;?><div class="form-text">Kumulativ: A gilt für A–D, B für B–D, C für C–D und D nur für D. Automatisch enthaltene höhere Klassen werden grau gesperrt.</div></div>
<div data-cumulative-classes><label class="form-label d-block">Rolloutklasse FI</label><?php foreach(['1','2','3'] as $c):?><label class="form-check form-check-inline"><input class="form-check-input" type="checkbox" name="technical[]" value="<?=$c?>" <?=in_array('technical:'.$c,$selected,true)?'checked':''?>> <?=$c?></label><?php endforeach;?></div><div data-cumulative-classes><label class="form-label d-block">Rolloutklasse DSV</label><?php foreach($dsvLevels as $level):?><label class="form-check form-check-inline"><input class="form-check-input" type="checkbox" name="dsv_class[]" value="<?=e($level['class_code'])?>" <?=in_array('dsv:'.$level['class_code'],$selected,true)?'checked':''?>> <?=e($level['class_label'])?></label><?php endforeach;?></div>
<div><label class="form-label d-block">Zuständige Leistungserbringer</label><?php foreach(['RV'=>'Regionalverbände','FI'=>'FI','DSV'=>'DSV'] as $target=>$label):?><label class="form-check form-check-inline"><input class="form-check-input" type="checkbox" name="provider_targets[]" value="<?=$target?>" <?=in_array($target,(array)($service['provider_targets']??[]),true)?'checked':''?>> <?=e($label)?></label><?php endforeach;?><div class="form-text">Regionalverbände verwenden Bankfachlich A–D, die FI 1–3 und der DSV sein eigenes Klassenschema.</div></div>
<div class="row g-3"><div class="col-md-6"><label class="form-label fw-semibold">Ist die Leistung obligatorisch?</label><select class="form-select" name="mandatory_for_all"><option value="0" <?=empty($service['mandatory_for_all'])?'selected':''?>>Nein – Bereitstellung abfragen</option><option value="1" <?=!empty($service['mandatory_for_all'])?'selected':''?>>Ja – automatisch als vorhanden setzen</option></select><div class="form-text">Bei „Ja“ entfällt die Abfrage, ob beziehungsweise wie die Leistung bereitgestellt wird.</div></div><div class="col-md-6"><label class="form-label fw-semibold">Ist ein Termin oder Zeitraum relevant?</label><select class="form-select" name="schedule_relevant"><option value="1" <?=!isset($service['schedule_relevant'])||$service['schedule_relevant']?'selected':''?>>Ja – Terminfeld anzeigen</option><option value="0" <?=isset($service['schedule_relevant'])&&!$service['schedule_relevant']?'selected':''?>>Nein – kein Terminfeld abfragen</option></select><div class="form-text">Das Bemerkungsfeld bleibt in beiden Fällen verfügbar.</div></div></div>
<div class="alert alert-light border small mb-0">Die jeweilige niedrigste Klasse gilt als Basis: Bankfachlich A, FI 1 und beim DSV die erste Klasse seines Schemas. Die Auswahl „obligatorisch“ kann darüber hinaus auch Leistungen höherer Klassen verbindlich setzen.</div><div class="d-flex gap-2"><button class="btn btn-primary">Zusätzliche Leistung speichern</button><a class="btn btn-outline-secondary" href="?page=matrix&project_id=<?=$projectId?>">Abbrechen</a></div></form>
<?php if($id):?><form method="post" class="mt-3"><?=csrf_field()?><input type="hidden" name="action" value="delete_custom_service"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="project_id" value="<?=$projectId?>"><button class="btn btn-link text-danger px-0" data-confirm="Zusätzliche Leistung einschließlich aller Matrixeinträge wirklich löschen?">Zusätzliche Leistung löschen</button></form><?php endif;?><?php }

function render_catalog(PDO $db,int $editId): void {
    $services=enrich_support_services($db,$db->query("SELECT s.* FROM support_services s WHERE s.is_standard=1 ORDER BY s.name COLLATE NOCASE")->fetchAll());foreach($services as &$service)$service['classes']=implode(',',$service['class_codes']);unset($service);
    $edit=['id'=>0,'name'=>'','description'=>'','is_standard'=>1,'project_id'=>null,'mandatory_for_all'=>0,'schedule_relevant'=>1,'active'=>1,'sort_order'=>0,'classes'=>'','provider_targets'=>['RV','FI','DSV']];if($editId)foreach($services as $s)if((int)$s['id']===$editId)$edit=$s;
    $selected=explode(',',(string)$edit['classes']);$dsvLevels=provider_class_levels($db,'DSV');$dsvClassCodes=array_column($dsvLevels,'class_code');$dsvClassLabels=array_column($dsvLevels,'class_label','class_code');$suggestions=$db->query("SELECT s.*,p.name project_name,r.name object_name,v.name provider_name,l.class_label FROM catalog_service_suggestions s JOIN projects p ON p.id=s.project_id JOIN rollout_objects r ON r.id=s.rollout_object_id JOIN providers v ON v.id=s.provider_id LEFT JOIN provider_class_levels l ON l.provider_type=s.provider_type AND l.class_code=s.class_code WHERE s.status='pending' ORDER BY s.created_at")->fetchAll();
    $activeTab=in_array((string)($_GET['tab']??''),['rv','fi','dsv'],true)?(string)$_GET['tab']:'rv';
    if($editId&&!isset($_GET['tab'])){$hasFunctional=(bool)array_filter($selected,fn($class)=>str_starts_with($class,'functional:'));$activeTab=$hasFunctional?'rv':'fi';}
    if(!$editId)$edit['provider_targets']=[$activeTab==='rv'?'RV':strtoupper($activeTab)];
    $tabs=[
        'rv'=>['label'=>'Regionalverbände','target'=>'RV','dimension'=>'functional','classes'=>['A','B','C','D'],'description'=>'Unterstützungsleistungen der Regionalverbände, gesteuert über die Klassen A–D'],
        'fi'=>['label'=>'FI','target'=>'FI','dimension'=>'technical','classes'=>['1','2','3'],'description'=>'Unterstützungsleistungen der FI, passend zur eigenen FI-Rolloutklasse 1–3'],
        'dsv'=>['label'=>'DSV','target'=>'DSV','dimension'=>'dsv','classes'=>$dsvClassCodes,'description'=>'Unterstützungsleistungen des DSV, passend zum eigenständig gepflegten DSV-Klassenschema'],
    ]; ?>
<div class="d-flex flex-wrap justify-content-between align-items-start gap-3 mb-4"><div><h1 class="page-title h2 mb-1">Katalog der Standardleistungen</h1><p class="text-secondary mb-0">Zentral gepflegte Leistungen, getrennt nach den zuständigen Leistungserbringern.</p></div><button class="btn <?=$editId?'btn-outline-secondary':'btn-primary'?>" type="button" data-bs-toggle="collapse" data-bs-target="#catalog-editor"><?=$editId?'Bearbeitungsformular ein-/ausblenden':'+ Standardleistung anlegen'?></button></div>
<div class="collapse <?=$editId?'show':''?> mb-4" id="catalog-editor"><form method="post" class="card p-4 vstack gap-3 catalog-editor"><?=csrf_field()?><input type="hidden" name="action" value="save_service"><input type="hidden" name="id" value="<?=$edit['id']?>"><input type="hidden" name="catalog_tab" value="<?=e($activeTab)?>"><h2 class="h5 mb-0"><?=$editId?'Standardleistung bearbeiten':'Standardleistung anlegen'?></h2>
<div><label class="form-label">Bezeichnung</label><input class="form-control" name="name" value="<?=e($edit['name'])?>" required></div>
<div class="alert alert-light border small mb-0"><strong>Einheitliche Ebene:</strong> Jede Unterstützungsleistung wird einem Projekt zugeordnet. Innerhalb des Projekts wird anschließend angehakt, für welche Rolloutobjekte sie genutzt wird.</div>
<div><label class="form-label">Beschreibung</label><textarea class="form-control" rows="3" name="description"><?=e($edit['description'])?></textarea></div>
<div><label class="form-label d-block fw-semibold">Zuständige Leistungserbringer</label><?php foreach(['RV'=>'Regionalverbände','FI'=>'FI','DSV'=>'DSV'] as $target=>$label):?><label class="form-check form-check-inline"><input class="form-check-input" type="checkbox" name="provider_targets[]" value="<?=$target?>" <?=in_array($target,(array)$edit['provider_targets'],true)?'checked':''?>> <?=e($label)?></label><?php endforeach;?><div class="form-text">FI und DSV können unabhängig voneinander zugeordnet werden.</div></div>
<div class="row g-3"><div class="col-lg-4"><div class="catalog-class-box h-100" data-cumulative-classes><label class="form-label d-block fw-semibold">Rolloutklasse Bankfachlich · A–D</label><?php foreach(['A','B','C','D'] as $c): ?><label class="form-check form-check-inline"><input class="form-check-input" type="checkbox" name="functional[]" value="<?=$c?>" <?=in_array('functional:'.$c,$selected,true)?'checked':''?>> <?=$c?></label><?php endforeach; ?><div class="form-text">Für Regionalverbände. Höhere Klassen werden automatisch markiert.</div></div></div><div class="col-lg-4"><div class="catalog-class-box h-100" data-cumulative-classes><label class="form-label d-block fw-semibold">Rolloutklasse FI · 1–3</label><?php foreach(['1','2','3'] as $c): ?><label class="form-check form-check-inline"><input class="form-check-input" type="checkbox" name="technical[]" value="<?=$c?>" <?=in_array('technical:'.$c,$selected,true)?'checked':''?>> <?=$c?></label><?php endforeach; ?><div class="form-text">Für Unterstützungsleistungen der FI. Höhere Klassen werden automatisch markiert.</div></div></div><div class="col-lg-4"><div class="catalog-class-box h-100" data-cumulative-classes><label class="form-label d-block fw-semibold">Rolloutklasse DSV</label><?php foreach($dsvLevels as $level):?><label class="form-check form-check-inline"><input class="form-check-input" type="checkbox" name="dsv_class[]" value="<?=e($level['class_code'])?>" <?=in_array('dsv:'.$level['class_code'],$selected,true)?'checked':''?>> <?=e($level['class_label'])?></label><?php endforeach;?><div class="form-text">Das Schema wird unter „Leistungserbringer“ gepflegt; höhere Klassen werden automatisch markiert.</div></div></div></div>
<div class="row g-3"><div class="col-md-6"><label class="form-label fw-semibold">Ist die Leistung obligatorisch?</label><select class="form-select" name="mandatory_for_all"><option value="0" <?=empty($edit['mandatory_for_all'])?'selected':''?>>Nein – Bereitstellung abfragen</option><option value="1" <?=!empty($edit['mandatory_for_all'])?'selected':''?>>Ja – automatisch als vorhanden setzen</option></select><div class="form-text">Bei „Ja“ entfällt die Abfrage, ob beziehungsweise wie die Leistung bereitgestellt wird.</div></div><div class="col-md-6"><label class="form-label fw-semibold">Ist ein Termin oder Zeitraum relevant?</label><select class="form-select" name="schedule_relevant"><option value="1" <?=!isset($edit['schedule_relevant'])||$edit['schedule_relevant']?'selected':''?>>Ja – Terminfeld anzeigen</option><option value="0" <?=isset($edit['schedule_relevant'])&&!$edit['schedule_relevant']?'selected':''?>>Nein – kein Terminfeld abfragen</option></select><div class="form-text">Das Bemerkungsfeld bleibt unabhängig davon verfügbar.</div></div></div>
<div class="alert alert-light border small mb-0">Eine Unterstützungsleistung kann gleichzeitig den Regionalverbänden, der FI und/oder dem DSV zugeordnet sein. Für jeden ausgewählten Bereich wird die dazugehörige Klasse separat gepflegt. Innerhalb einer Klasse zeigt der Katalog die Leistungen alphabetisch an.</div><?php if($editId): ?><label class="form-check"><input type="checkbox" class="form-check-input" name="active" <?=$edit['active']?'checked':''?>> Aktiv</label><?php endif; ?><div class="d-flex gap-2"><button class="btn btn-primary">Speichern</button><?php if($editId): ?><a class="btn btn-outline-secondary" href="?page=catalog&tab=<?=e($activeTab)?>">Abbrechen</a><?php endif; ?></div></form></div>
<?php if($suggestions):?><div class="card p-3 p-lg-4 mb-4"><h2 class="h5">Offene DSV-Katalogvorschläge</h2><p class="small text-secondary">Diese Leistungen wurden in einer Phase-2-Datei neu vorgeschlagen. Erst nach deiner Freigabe werden sie Bestandteil des zentralen Standardkatalogs.</p><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Vorschlag</th><th>Projekt / Rolloutobjekt</th><th>Klasse</th><th>Termin / Bemerkung</th><th></th></tr></thead><tbody><?php foreach($suggestions as $suggestion):?><tr><td class="fw-semibold"><?=e($suggestion['proposed_name'])?></td><td><?=e($suggestion['project_name'].' / '.$suggestion['object_name'])?></td><td><?=e($suggestion['class_label']??$suggestion['class_code'])?></td><td><span class="d-block"><?=e($suggestion['schedule'])?></span><span class="small text-secondary"><?=e($suggestion['note'])?></span></td><td class="text-nowrap"><form method="post" class="d-inline"><?=csrf_field()?><input type="hidden" name="action" value="accept_catalog_suggestion"><input type="hidden" name="id" value="<?=$suggestion['id']?>"><button class="btn btn-sm btn-primary">In Katalog übernehmen</button></form> <form method="post" class="d-inline"><?=csrf_field()?><input type="hidden" name="action" value="reject_catalog_suggestion"><input type="hidden" name="id" value="<?=$suggestion['id']?>"><button class="btn btn-sm btn-outline-secondary">Ablehnen</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?>
<div class="card p-3 p-lg-4"><div class="row g-2 mb-3"><div class="col-lg-8"><input id="catalog-search" class="form-control" type="search" placeholder="Leistung oder Beschreibung suchen …" aria-label="Leistungen durchsuchen"></div><div class="col-sm-6 col-lg-4"><select id="catalog-status-filter" class="form-select"><option value="active">Nur aktive Leistungen</option><option value="all">Aktive und inaktive</option><option value="inactive">Nur inaktive Leistungen</option></select></div></div>
<ul class="nav nav-tabs catalog-tabs" role="tablist"><?php foreach($tabs as $tabKey=>$tab):?><li class="nav-item"><button class="nav-link <?=$activeTab===$tabKey?'active':''?>" data-bs-toggle="tab" data-bs-target="#catalog-panel-<?=$tabKey?>" type="button"><span><?=$tab['label']?></span><span class="badge rounded-pill text-bg-light ms-2" data-tab-count>0</span></button></li><?php endforeach;?></ul>
