<script>(()=>{const search=document.getElementById('catalog-search'),status=document.getElementById('catalog-status-filter');if(!search||!status)return;const filter=()=>{const query=search.value.trim().toLocaleLowerCase('de');document.querySelectorAll('[id^="catalog-panel-"]').forEach(panel=>{let panelCount=0;panel.querySelectorAll('[data-catalog-group]').forEach(group=>{let groupCount=0;group.querySelectorAll('[data-catalog-service]').forEach(service=>{const visible=(!query||service.dataset.search.includes(query))&&(status.value==='all'||service.dataset.status===status.value);service.hidden=!visible;if(visible){groupCount++;panelCount++;}});group.hidden=groupCount===0;const badge=group.querySelector('[data-group-count]');if(badge)badge.textContent=groupCount+' '+(groupCount===1?'Leistung':'Leistungen');});const empty=panel.querySelector('.catalog-no-results');if(empty)empty.hidden=panelCount!==0;const summary=panel.querySelector('[data-result-summary]');if(summary)summary.textContent=panelCount+' Leistung'+(panelCount===1?'':'en')+' angezeigt';const badge=document.querySelector('[data-bs-target="#'+panel.id+'"] [data-tab-count]');if(badge)badge.textContent=String(panelCount);});};[search,status].forEach(control=>control.addEventListener(control===search?'input':'change',filter));filter();})();</script><?php }

